async setBlockedContent(aBlockedURI) {
  const [buttonLabel, buttonAccesskey] = await document.l10n.formatValues([
    AppConstants.platform == "win"
      ? "compose-blocked-content-options-button"
      : "compose-blocked-content-preferences-button",
    AppConstants.platform == "win"
      ? "compose-blocked-content-options-accesskey"
      : "compose-blocked-content-preferences-accesskey",
  ]);

  const buttons = [
    {
      label: buttonLabel,
      accessKey: buttonAccesskey,
      popup: "blockedContentOptions",
      callback() {
        return true; // keep notification open
      },
    },
  ];

  // The popup value is a space separated list of all the blocked urls.
  const popup = document.getElementById("blockedContentOptions");
  const urls = popup.value ? popup.value.split(" ") : [];
  if (!urls.includes(aBlockedURI)) {
    urls.push(aBlockedURI);
  }
  popup.value = urls.join(" ");

  if (!this.isShowingBlockedContentNotification()) {
    await gComposeNotification.appendNotification(
      "blockedContent",
      {
        label: {
          "l10n-id": "blocked-content-message",
          "l10n-args": { count: urls.length },
        },
        priority: gComposeNotification.PRIORITY_WARNING_MEDIUM,
      },
      buttons
    );
  } else {
    document.l10n.setAttributes(
      gComposeNotification.getNotificationWithValue("blockedContent")
        .messageText,
      "blocked-content-message",
      { count: urls.length }
    );
  }
},
